/**
 * @file    sim_main.c
 * @brief   SIMULATION BUILD of the Wildlife Intrusion Sentinel firmware.
 *
 * DO NOT EDIT. Generated from firmware/app/main.c by simulation/tools/gen_sim.py.
 * Change main.c and re-run that script.
 *
 * This is byte-for-byte the submission firmware with ONE line changed:
 *
 *     #define MACHINE_TELEMETRY  1      (main.c has 0)
 *
 * which swaps the human-readable Bluetooth output for terse machine-readable lines
 * that simulation/swis_gui.py parses. Pin map, state machine, timings, validation
 * rule and deterrent behaviour are all identical. Flash whichever you want.
 *
 * BUILD: simulation/firmware/sim_main.c + firmware/common/board.c
 *        (same Keil options and include path as main.c)
 *
 * TELEMETRY PROTOCOL - every line ends CR LF.
 *     EV,SRC=IR                  a sensor fired, sent the instant it happens
 *     ST,<STATE>,DETER=0|1       state changed; DETER = deterrent running
 *     ALERT,ZONE1,ANIMAL BREACH  the farmer notification
 *     SWIS,STATE=..,BREACH=..,FALSE=..,AWAY=..,LDR=..,ZONE=A|B,DEMO=0|1,DAY|NIGHT
 *
 * Event lines go out the instant a sensor fires, so the animal on screen starts
 * moving in step with the hand that broke the beam.
 */
#include "board.h"

/* ============================ TUNING ============================ */
#define PIR_WARMUP_MS      30000u   /* PIR settling time after power-up             */
#define APPROACH_MS        15000u   /* how long an approach stays 'live' at the fence */
#define CHIRP_MS             120u   /* length of each perimeter warning chirp       */
#define CHIRP_GAP_MS        1400u   /* gap between chirps - deliberately unhurried  */
#define BREACH_MS          10000u   /* how long the deterrent runs                  */
#define COOLDOWN_MS         3000u   /* quiet period after a breach                  */
#define IR_DEBOUNCE_MS       200u   /* ignore repeat IR edges inside this           */
#define LCD_REFRESH_MS       500u   /* how often the LCD may be rewritten           */

#define DARK_THRESHOLD      2500u   /* ADC reading above this = dark (see test_ldr.c) */
#define LDR_DARK_IS_HIGH        1   /* set to 0 if your module reads LOW when dark  */

/* ============ WHAT IS ACTUALLY FITTED AND WORKING ON THE BENCH ============
 * Set a line to 0 and the firmware stops depending on that part. Nothing else needs
 * changing, and the system stays fully functional on what is left.
 *
 *   PIR_FITTED 0   the PIR on PB5 is not producing an output yet. It is excluded
 *                  from validation entirely, so it can never block a breach. The
 *                  30 s warm-up is KEPT anyway - it is a useful "system starting"
 *                  indication and costs nothing.
 *   SIREN_FITTED 0 no 12 V siren on the relay contacts (no barrel-jack adapter yet).
 *                  The relay is still driven, so it audibly clicks at the moment of a
 *                  breach and the switching is demonstrated. Only the status text
 *                  changes, so nothing claims a siren sounded when none is attached.
 *
 * With PIR_FITTED 0 the working detectors are the IR beam (PA0) and the vibration
 * sensor (PA2). Those two can still confirm each other, so the two-sensor rule below
 * still means something: break the beam AND tap the board within 2 s. If that is
 * awkward during a demo, press D over Bluetooth for single-sensor mode (see below). */
#define PIR_FITTED              0
#define SIREN_FITTED            0

/* 0 = human-readable output for the Bluetooth terminal (aligned, labelled blocks).
 * 1 = terse machine-readable lines for simulation/swis_gui.py to parse.
 * This single flag is the ONLY difference between this file and the simulation
 * build, which is generated by flipping it. */
#define MACHINE_TELEMETRY       1

/* 1 = two sensors needed in daylight (fewer false alarms).
 * 0 = any single sensor triggers a breach at any time. */
#define REQUIRE_SECOND_SENSOR   1

/* The IR beam is the physical line between the two zones, so the sensors do not
 * "own" a zone - they mark which side of the line the animal has reached:
 *     vibration / PIR fire while it is still OUTSIDE  -> ZONE_A, the perimeter
 *     the beam breaking means it has crossed INSIDE   -> ZONE_B, the field */
#define ZONE_PERIMETER  ZONE_A
#define ZONE_FIELD      ZONE_B

/* ============================ STATE ============================ */
typedef enum { ST_WARMUP, ST_SECURE, ST_APPROACH, ST_BREACH, ST_COOLDOWN } state_t;

volatile state_t  state        = ST_WARMUP;
volatile uint32_t breach_count = 0;   /* confirmed breaches                          */
volatile uint32_t false_alarms = 0;   /* beam breaks with no approach: bird, leaf    */
volatile uint32_t approaches   = 0;   /* animals detected at the fence               */
volatile uint32_t turned_away  = 0;   /* approached but never crossed - a win        */
volatile uint32_t ir_events    = 0;
volatile uint32_t pir_events   = 0;
volatile uint32_t vib_events   = 0;
volatile uint16_t ldr_value    = 0;
volatile uint8_t  is_night     = 0;
volatile uint8_t  lcd_ok       = 0;   /* 0 = no LCD found; system runs without it    */
volatile uint8_t  breach_zone  = ZONE_A; /* which side fired: ZONE_A or ZONE_B       */
volatile uint8_t  demo_mode    = 0;   /* 1 = one sensor is enough (toggle with D)    */

static uint32_t state_since = 0;      /* millis() when the current state began       */

/* set by the IR interrupt, cleared by the main loop */
static volatile uint8_t  ir_flag    = 0;
static volatile uint32_t ir_last_ms = 0;

/* ======================= IR on PA0 (EXTI0) ======================= */
void EXTI0_IRQHandler(void)
{
    if (EXTI->PR & EXTI_PR_PR0) {
        EXTI->PR = EXTI_PR_PR0;                      /* clear pending (write 1) */
        uint32_t now = millis();
        if ((now - ir_last_ms) > IR_DEBOUNCE_MS) {
            ir_last_ms = now;
            ir_events++;
            ir_flag = 1;
        }
    }
}

static void ir_init(void)
{
    gpio_mode(IR_PORT, IR_PIN, BRD_MODE_IN);
#if IR_ACTIVE_LOW
    gpio_pull(IR_PORT, IR_PIN, BRD_PULL_UP);
#elif IR_EXT_PULLUP
    gpio_pull(IR_PORT, IR_PIN, BRD_PULL_NONE);       /* external 10k on the NPN collector */
#else
    gpio_pull(IR_PORT, IR_PIN, BRD_PULL_DOWN);
#endif
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;
    (void)RCC->APB2ENR;
    SYSCFG->EXTICR[0] &= ~SYSCFG_EXTICR1_EXTI0;      /* EXTI0 <- port A */
    EXTI->IMR |= EXTI_IMR_MR0;
#if IR_ACTIVE_LOW
    EXTI->FTSR |= EXTI_FTSR_TR0;  EXTI->RTSR &= ~EXTI_RTSR_TR0;
#else
    EXTI->RTSR |= EXTI_RTSR_TR0;  EXTI->FTSR &= ~EXTI_FTSR_TR0;
#endif
    EXTI->PR = EXTI_PR_PR0;
    NVIC_SetPriority(EXTI0_IRQn, 0);
    NVIC_EnableIRQ(EXTI0_IRQn);
}

/* ==================== PIR (PB5) and vibration (PA2) ==================== */
static void sensors_init(void)
{
    gpio_mode(PIR_PORT, PIR_PIN, BRD_MODE_IN);
    gpio_pull(PIR_PORT, PIR_PIN, BRD_PULL_DOWN);
    gpio_mode(VIB_PORT, VIB_PIN, BRD_MODE_IN);
    gpio_pull(VIB_PORT, VIB_PIN, BRD_PULL_DOWN);
}

static uint8_t pir_active(void)
{
#if PIR_FITTED
    uint8_t v = gpio_read(PIR_PORT, PIR_PIN);
    return (uint8_t)(PIR_ACTIVE_HIGH ? v : !v);
#else
    return 0;                     /* not fitted - never votes, never blocks a breach */
#endif
}

static uint8_t vib_active(void)
{
    uint8_t v = gpio_read(VIB_PORT, VIB_PIN);
    return (uint8_t)(VIB_ACTIVE_HIGH ? v : !v);
}

/* ======================= LDR on PA4 (ADC1_IN4) ======================= */
static void adc1_init(void)
{
    gpio_mode(LDR_PORT, LDR_PIN, BRD_MODE_ANALOG);
    RCC->APB2ENR |= RCC_APB2ENR_ADC1EN;
    (void)RCC->APB2ENR;
    ADC1->SMPR2 |= (7u << (3u * 4u));                /* channel 4: long sample time */
    ADC1->SQR1   = 0;
    ADC1->SQR3   = 4u;
    ADC1->CR2   |= ADC_CR2_ADON;
    delay_ms(2);
}

static uint16_t adc1_read(void)
{
    ADC1->CR2 |= ADC_CR2_SWSTART;
    while (!(ADC1->SR & ADC_SR_EOC)) { }
    return (uint16_t)ADC1->DR;
}

/* ============ Buzzers (PA6, and PB0 when BUZ2_ENABLE) and relay (PA7) ============
 * buzzer_init() and buzzer_set() live in board.c so that wiring a second buzzer is a
 * board.h change and nothing here needs touching. They drive both buzzers together. */

/* Active-low opto relay boards are driven open-drain: the MCU only ever pulls the input
 * to GND, never tries to present 3.3 V to a 5 V-referenced input. Same scheme as
 * test_actuators.c and test_siren.c. */
static void relay_set(uint8_t on)
{
#if RELAY_ACTIVE_LOW
    gpio_write(RELAY_PORT, RELAY_PIN, on ? 0 : 1);
#else
    gpio_write(RELAY_PORT, RELAY_PIN, on ? 1 : 0);
#endif
}

static void relay_init(void)
{
    relay_set(0);                                    /* OFF before the pin drives */
#if RELAY_ACTIVE_LOW
    gpio_open_drain(RELAY_PORT, RELAY_PIN, 1);
#endif
    gpio_mode(RELAY_PORT, RELAY_PIN, BRD_MODE_OUT);
}

/* Varying buzzer cadence, driven from millis() so it never blocks the main loop.
 * The pattern changes on purpose: a constant tone is something animals get used to. */
static void buzzer_pattern(uint32_t now, uint8_t active)
{
    static uint32_t next_ms = 0;
    static uint32_t step    = 0;
    static uint8_t  on      = 0;

    if (!active) {
        if (on) { on = 0; buzzer_set(0); }
        next_ms = now;
        step = 0;
        return;
    }
    if ((int32_t)(now - next_ms) < 0) return;

    on = (uint8_t)!on;
    buzzer_set(on);
    if (on) next_ms = now + 60u + 40u * (step % 4u);
    else  { next_ms = now + 200u - 40u * (step % 4u); step++; }
}

/* ========================= LCD on I2C1 (PB6/PB7) ========================= */
#define LCD_RS  0x01u
#define LCD_EN  0x04u
#define LCD_BL  0x08u

static uint8_t lcd_addr = 0x27;

static void i2c1_init(void)
{
    RCC->APB1ENR |= RCC_APB1ENR_I2C1EN;
    (void)RCC->APB1ENR;
    gpio_af(GPIOB, 6, 4);  gpio_af(GPIOB, 7, 4);
    gpio_open_drain(GPIOB, 6, 1);  gpio_open_drain(GPIOB, 7, 1);
    gpio_pull(GPIOB, 6, BRD_PULL_NONE);  gpio_pull(GPIOB, 7, BRD_PULL_NONE);
    gpio_mode(GPIOB, 6, BRD_MODE_AF);    gpio_mode(GPIOB, 7, BRD_MODE_AF);

    I2C1->CR1 |= I2C_CR1_SWRST;  I2C1->CR1 &= ~I2C_CR1_SWRST;
    I2C1->CR2   = 16u;
    I2C1->CCR   = 80u;
    I2C1->TRISE = 17u;
    I2C1->CR1 |= I2C_CR1_PE;
}

static int i2c_write_byte(uint8_t addr7, uint8_t data)
{
    int rc = -1;
    uint32_t t;

    I2C1->CR1 |= I2C_CR1_START;
    t = millis();
    while (!(I2C1->SR1 & I2C_SR1_SB)) { if (millis() - t > 5u) goto done; }
    I2C1->DR = (uint8_t)(addr7 << 1);
    t = millis();
    while (!(I2C1->SR1 & (I2C_SR1_ADDR | I2C_SR1_AF))) { if (millis() - t > 5u) goto done; }
    if (I2C1->SR1 & I2C_SR1_AF) { I2C1->SR1 &= ~I2C_SR1_AF; goto done; }
    (void)I2C1->SR1; (void)I2C1->SR2;
    t = millis();
    while (!(I2C1->SR1 & I2C_SR1_TXE)) { if (millis() - t > 5u) goto done; }
    I2C1->DR = data;
    t = millis();
    while (!(I2C1->SR1 & I2C_SR1_BTF)) { if (millis() - t > 5u) goto done; }
    rc = 0;
done:
    I2C1->CR1 |= I2C_CR1_STOP;
    return rc;
}

static void lcd_nibble(uint8_t nib, uint8_t rs)
{
    uint8_t d = (uint8_t)((nib << 4) | LCD_BL | (rs ? LCD_RS : 0u));
    i2c_write_byte(lcd_addr, (uint8_t)(d | LCD_EN));
    i2c_write_byte(lcd_addr, (uint8_t)(d & (uint8_t)~LCD_EN));
}

static void lcd_send(uint8_t byte, uint8_t rs)
{
    lcd_nibble((uint8_t)(byte >> 4), rs);
    lcd_nibble((uint8_t)(byte & 0x0Fu), rs);
}

static void lcd_cmd(uint8_t c) { lcd_send(c, 0); delay_ms(2); }
static void lcd_putc(char c)   { lcd_send((uint8_t)c, 1); }
static void lcd_goto(uint8_t col, uint8_t row) { lcd_cmd((uint8_t)(0x80u | ((row ? 0x40u : 0u) + col))); }

static void lcd_init(void)
{
    delay_ms(50);
    lcd_nibble(0x3, 0); delay_ms(5);
    lcd_nibble(0x3, 0); delay_ms(1);
    lcd_nibble(0x3, 0); delay_ms(1);
    lcd_nibble(0x2, 0); delay_ms(1);
    lcd_cmd(0x28); lcd_cmd(0x08); lcd_cmd(0x01); lcd_cmd(0x06); lcd_cmd(0x0C);
}

/* Write one 16-character line, padding with spaces so old text is erased. */
static void lcd_line(uint8_t row, const char *s)
{
    uint8_t i;
    uint8_t ended = 0;
    if (!lcd_ok) return;
    lcd_goto(0, row);
    for (i = 0; i < 16u; i++) {
        if (!ended && s[i] == '\0') ended = 1;
        lcd_putc(ended ? ' ' : s[i]);
    }
}

/* ===================== HC-05 on USART1 (PA9/PA10) ===================== */
#define BAUD  9600u

static void uart1_init(void)
{
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;
    (void)RCC->APB2ENR;
    gpio_af(GPIOA, 9, 7);  gpio_af(GPIOA, 10, 7);
    gpio_mode(GPIOA, 9, BRD_MODE_AF);
    gpio_mode(GPIOA, 10, BRD_MODE_AF);
    gpio_pull(GPIOA, 10, BRD_PULL_UP);
    USART1->BRR = (SystemCoreClock + BAUD / 2u) / BAUD;
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;
}

static void uart_putc(char c) { while (!(USART1->SR & USART_SR_TXE)) { } USART1->DR = (uint8_t)c; }
static void uart_puts(const char *s) { while (*s) uart_putc(*s++); }

static void uart_putu(uint32_t v)
{
    char b[11]; int i = 0;
    if (!v) { uart_putc('0'); return; }
    while (v) { b[i++] = (char)('0' + v % 10u); v /= 10u; }
    while (i) uart_putc(b[--i]);
}

static const char *const state_names[] = {
    "WARMING UP", "SECURE", "APPROACH", "BREACH", "COOLDOWN"
};

/* Pad a label out to a fixed width so the phone screen lines up in a column.
 * A wall of comma-separated text is unreadable over someone's shoulder; aligned
 * labels can be read at a glance from across a room. */
static void uart_field(const char *label, uint8_t width)
{
    uint8_t n = 0;
    uart_puts("  ");
    while (label[n]) { uart_putc(label[n]); n++; }
    while (n < width) { uart_putc(' '); n++; }
    uart_puts(": ");
}

static void uart_rule(void)
{
    uart_puts("  ----------------------------\r\n");
}

/* One event line, called the moment something happens. Blank line first so each
 * event stands apart from the status blocks instead of running into them. */
static void report_line(const char *tag, const char *detail)
{
#if MACHINE_TELEMETRY
    (void)tag; (void)detail;      /* the machine build announces states via go() */
#else
    uart_puts("\r\n>> ");
    uart_puts(tag);
    uart_puts("  -  ");
    uart_puts(detail);
    uart_puts("\r\n");
#endif
}

static void send_status(void)
{
#if MACHINE_TELEMETRY
    /* One terse line for simulation/swis_gui.py. */
    uart_puts("SWIS,STATE="); uart_puts(state_names[state]);
    uart_puts(",BREACH=");    uart_putu(breach_count);
    uart_puts(",FALSE=");     uart_putu(false_alarms);
    uart_puts(",AWAY=");      uart_putu(turned_away);
    uart_puts(",LDR=");       uart_putu(ldr_value);
    uart_puts((breach_zone == ZONE_A) ? ",ZONE=A" : ",ZONE=B");
    uart_puts(demo_mode ? ",DEMO=1" : ",DEMO=0");
    uart_puts(is_night ? ",NIGHT\r\n" : ",DAY\r\n");
#else
    uart_puts("\r\n");
    uart_rule();
    uart_puts("   WILDLIFE SENTINEL - STATUS\r\n");
    uart_rule();

    uart_field("State", 10);     uart_puts(state_names[state]);      uart_puts("\r\n");
    uart_field("Perimeter", 10);
    uart_puts((state == ST_APPROACH) ? "ANIMAL AT FENCE" : "clear");  uart_puts("\r\n");
    uart_field("Field", 10);
    uart_puts((state == ST_BREACH) ? "INTRUDER INSIDE" : "clear");    uart_puts("\r\n");
    uart_rule();
    uart_field("Breaches", 10);  uart_putu(breach_count);  uart_puts("   (crossed the beam)\r\n");
    uart_field("Turned away", 10); uart_putu(turned_away); uart_puts("   (left at the fence)\r\n");
    uart_field("Approaches", 10); uart_putu(approaches);   uart_puts("\r\n");
    uart_field("Filtered", 10);  uart_putu(false_alarms);  uart_puts("   (bird / leaf / gust)\r\n");
    uart_rule();
    uart_field("Light", 10);     uart_putu(ldr_value);
    uart_puts(is_night ? "  (NIGHT - one sensor is enough)\r\n"
                       : "  (DAY - approach must come first)\r\n");
    uart_field("Mode", 10);
    uart_puts(demo_mode ? "DEMO - any single sensor triggers\r\n" : "normal\r\n");
#if !PIR_FITTED
    uart_field("PIR", 10);       uart_puts("offline (not fitted)\r\n");
#endif
#if !SIREN_FITTED
    uart_field("Siren", 10);     uart_puts("not fitted (relay still switches)\r\n");
#endif
    uart_rule();
#endif  /* MACHINE_TELEMETRY */
}

/* Every state change goes through here, so the machine build can announce each one
 * exactly once without transitions being scattered through the state machine. */
static void go(state_t s, uint32_t now)
{
    state       = s;
    state_since = now;
#if MACHINE_TELEMETRY
    uart_puts("ST,"); uart_puts(state_names[state]);
    uart_puts((state == ST_BREACH) ? ",DETER=1\r\n" : ",DETER=0\r\n");
#endif
}

#if MACHINE_TELEMETRY
/* Sent the instant a sensor fires, so the GUI animation starts in step with the
 * hand that broke the beam rather than on the next heartbeat. */
static void emit_event(const char *src)
{
    uart_puts("EV,SRC="); uart_puts(src); uart_puts("\r\n");
}
#else
#define emit_event(src)   ((void)0)
#endif

/* Soft, slow warning chirp on the PERIMETER buzzer only. Deliberately unhurried and
 * on one buzzer, so it is instantly distinguishable from the two-buzzer breach
 * cadence - a nudge to move the animal on, not an alarm. */
static void chirp(uint32_t now)
{
    static uint32_t next_ms = 0;
    static uint8_t  on      = 0;

    if ((int32_t)(now - next_ms) < 0) return;
    on = (uint8_t)!on;
    buzzer_mask(BUZZER_1, on);
    next_ms = now + (on ? CHIRP_MS : CHIRP_GAP_MS);
}

static void chirp_off(void) { buzzer_mask(BUZZER_1, 0); }

/* The animal has crossed the beam into the field. Everything escalates at once. */
static void start_breach(uint32_t now)
{
    breach_count++;
    breach_zone = ZONE_FIELD;
    relay_set(1);
    go(ST_BREACH, now);
    report_line("BREACH", "animal crossed the beam - deterrent ON");
#if MACHINE_TELEMETRY
    uart_puts("ALERT,ZONE1,ANIMAL BREACH\r\n");
#else
    uart_puts("   ZONE 1: ANIMAL BREACH - alert sent to farmer\r\n");
#endif
    send_status();
}

/* LCD line 2. Shows what the two zones are doing right now, not a bare count -
 * "ZONE A  B=0" read like zone A had zero of something, which it never meant. */
static void make_line2(char *out)
{
    const char *tag;
    uint32_t n = breach_count;
    int i = 0;

    switch (state) {
    case ST_APPROACH: tag = "At fence  No:"; break;
    case ST_BREACH:   tag = "In field  No:"; break;
    case ST_COOLDOWN: tag = "Clearing  No:"; break;
    default:          tag = "All clear No:"; break;
    }

    while (tag[i] && i < 16) { out[i] = tag[i]; i++; }
    if (n == 0) {
        if (i < 16) out[i++] = '0';
    } else {
        char tmp[11]; int k = 0;
        while (n && k < 11) { tmp[k++] = (char)('0' + n % 10u); n /= 10u; }
        while (k && i < 16) out[i++] = tmp[--k];
    }
    out[i] = '\0';
}

/* ===================== Indicator LEDs - ONE decision point =====================
 * PA5 is both the status LED and the zone A indicator, so every decision about either
 * LED is made here and nowhere else. If the state machine also called led_set() the two
 * roles would overwrite each other on the same pin.
 *
 * The two LEDs read left to right as the animal's progress across the boundary:
 *
 *   WARMUP    PA5 slow blink                   settling, not armed yet
 *   SECURE    PA5 short heartbeat flash        armed and healthy
 *   APPROACH  PA5 BLINKING,  PA8 off           at the fence, still outside
 *   BREACH    PA5 on,        PA8 SOLID         crossed - it is in the field
 *   COOLDOWN  PA5 off,       PA8 slow blink    clearing
 *
 * So one lit LED means the perimeter, two lit means it got through. SECURE is a
 * heartbeat rather than steady-on deliberately, so that a steadily lit LED always
 * means "something is here" and never just "powered on". */
static void indicators(uint32_t now)
{
    uint8_t a = 0, b = 0;

    switch (state) {
    case ST_WARMUP:
        a = (uint8_t)((now / 500u) & 1u);
        break;
    case ST_SECURE:
        a = (uint8_t)((now % 2000u) < 100u);          /* brief flash every 2 s */
        break;
    case ST_APPROACH:
        a = (uint8_t)((now / 300u) & 1u);             /* perimeter blinking: at the fence */
        break;
    case ST_BREACH:
        a = 1;                                        /* came through here... */
        b = 1;                                        /* ...and is now in the field */
        break;
    case ST_COOLDOWN:
        b = (uint8_t)((now / 500u) & 1u);
        break;
    default:
        break;
    }

    zone_led_set(ZONE_A, a);
    zone_led_set(ZONE_B, b);
}

/* ============================== MAIN ============================== */
int main(void)
{
    uint32_t now;
    uint32_t last_lcd    = 0;
    uint32_t last_ldr    = 0;
    uint32_t last_beacon = 0;
    uint8_t  pir_prev, vib_prev;
    uint32_t ir_seen = 0;         /* last ir_events value already announced      */
    const char *lcd_top   = "";
    const char *lcd_shown = 0;

    board_init();
    led_init();
    relay_init();                 /* relay OFF first, so the siren cannot bang at reset */
    buzzer_init();
    zone_leds_init();             /* both zone LEDs off */
    sensors_init();
    ir_init();
    adc1_init();
    uart1_init();
    i2c1_init();

    /* The LCD is optional: if no backpack answers, lcd_ok stays 0 and every lcd_*
     * call becomes a no-op instead of hanging the system. */
    if      (i2c_write_byte(0x27, LCD_BL) == 0) { lcd_addr = 0x27; lcd_ok = 1; }
    else if (i2c_write_byte(0x3F, LCD_BL) == 0) { lcd_addr = 0x3F; lcd_ok = 1; }
    if (lcd_ok) lcd_init();

    lcd_line(0, "SWIS STARTING");
    lcd_line(1, "PIR warming up");
    uart_puts("\r\nSWIS ready. ? for help.\r\n");

    pir_prev    = pir_active();
    vib_prev    = vib_active();
    go(ST_WARMUP, millis());

    for (;;) {
        now = millis();

        /* ---------- read the light level a few times a second ---------- */
        if ((now - last_ldr) >= 250u) {
            last_ldr  = now;
            ldr_value = adc1_read();
#if LDR_DARK_IS_HIGH
            is_night = (uint8_t)(ldr_value > DARK_THRESHOLD);
#else
            is_night = (uint8_t)(ldr_value < DARK_THRESHOLD);
#endif
        }

        /* ---------- sample the polled sensors, count rising edges ---------- */
        {
            uint8_t p = pir_active();
            uint8_t v = vib_active();
            if (p && !pir_prev) { pir_events++; emit_event("PIR"); }
            if (v && !vib_prev) { vib_events++; emit_event("VIB"); }
            if (ir_events != ir_seen) { ir_seen = ir_events; emit_event("IR"); }
            pir_prev = p;
            vib_prev = v;
        }

        /* ---------- Bluetooth commands (non-blocking) ---------- */
        if (USART1->SR & USART_SR_RXNE) {
            char c = (char)USART1->DR;
            switch (c) {
                case '?':
                    uart_puts("\r\n");
                    uart_rule();
                    uart_puts("   COMMANDS\r\n");
                    uart_rule();
                    uart_field("S", 3); uart_puts("status report\r\n");
                    uart_field("R", 3); uart_puts("reset to secure\r\n");
                    uart_field("A", 3); uart_puts("simulate an approach at the fence\r\n");
                    uart_field("B", 3); uart_puts("simulate a breach (full alarm)\r\n");
                    uart_field("T", 3); uart_puts("2 second deterrent test\r\n");
                    uart_field("M", 3); uart_puts("reversing-beep tone test\r\n");
                    uart_field("D", 3); uart_puts("demo mode: one sensor is enough\r\n");
                    uart_rule();
                    break;
                case 'S': case 's':
                    send_status();
                    break;
                case 'R': case 'r':
                    relay_set(0);
                    buzzer_pattern(now, 0);
                    chirp_off();
                    zone_leds_off();
                    go(ST_SECURE, now);
                    report_line("RESET", "back to secure");
                    break;
                case 'A': case 'a':
                    /* Stage the demo by hand when tapping the board is awkward. */
                    approaches++;
                    breach_zone = ZONE_PERIMETER;
                    go(ST_APPROACH, now);
                    report_line("APPROACH", "movement at the perimeter (simulated)");
                    break;
                case 'B': case 'b':
                    start_breach(now);
                    break;
                case 'D': case 'd':
                    /* Demo mode: one sensor is enough, at any time of day. For a
                     * presentation where tapping the board and breaking the beam in
                     * the right order is awkward with one free hand. */
                    demo_mode = (uint8_t)!demo_mode;
                    report_line(demo_mode ? "DEMO MODE ON" : "DEMO MODE OFF",
                                demo_mode ? "any single sensor now triggers a breach"
                                          : "daylight needs an approach before the beam");
                    break;
                case 'T': case 't': {
                    uint32_t t0 = millis();
                    report_line("TEST", "deterrent, 2 seconds");
                    relay_set(1);
                    while ((millis() - t0) < 2000u) buzzer_pattern(millis(), 1);
                    buzzer_pattern(millis(), 0);
                    relay_set(0);
                    break;
                }
                case 'M': case 'm': {
                    /* Reversing-beep tone test: the steady, evenly spaced beep a car
                     * makes in reverse. Purely a sound check - it touches no state,
                     * no relay and no counters, so it is safe to run at any time. */
                    uint8_t k;
                    report_line("TONE TEST", "reversing beep, 5 seconds");
                    for (k = 0; k < 10u; k++) {
                        buzzer_set(1); delay_ms(170);
                        buzzer_set(0); delay_ms(330);
                    }
                    break;
                }
                default:
                    break;
            }
        }
        if (USART1->SR & USART_SR_ORE) { (void)USART1->SR; (void)USART1->DR; }

        /* ======================== STATE MACHINE ======================== */
        switch (state) {

        case ST_WARMUP:
            lcd_top = "SWIS STARTING";
            ir_flag = 0;                                 /* ignore triggers while settling */
            if ((now - state_since) >= PIR_WARMUP_MS) {
                go(ST_SECURE, now);
                report_line("ARMED", "warm-up complete, system watching");
            }
            break;

        case ST_SECURE:
            lcd_top = "STATUS: SECURE";
            /* Ground vibration means something heavy is at the fence but still
             * OUTSIDE. That is a warning, not an alarm: escalate to APPROACH. */
            if (vib_active() || pir_active()) {
                approaches++;
                breach_zone = ZONE_PERIMETER;
                go(ST_APPROACH, now);
                report_line("APPROACH", "movement at the perimeter");
            }
            /* The beam breaking means something CROSSED. With no approach logged
             * first it is almost always a bird, a leaf or a gust, so in daylight it
             * is filtered out. At night, or in demo mode, one sensor is enough. */
            else if (ir_flag) {
                ir_flag = 0;
                if (!REQUIRE_SECOND_SENSOR || is_night || demo_mode) {
                    start_breach(now);
                } else {
                    false_alarms++;
                    report_line("IGNORED", "beam only, nothing approached first");
                }
            }
            break;

        case ST_APPROACH:
            lcd_top = "APPROACH";
            chirp(now);                         /* soft warning, perimeter buzzer only */
            if (vib_active()) state_since = now;        /* still out there - hold open */
            if (ir_flag) {
                ir_flag = 0;
                chirp_off();
                start_breach(now);                      /* it crossed the line */
            } else if ((now - state_since) >= APPROACH_MS) {
                turned_away++;
                chirp_off();
                go(ST_SECURE, now);
                report_line("TURNED AWAY", "left without crossing the beam");
            }
            break;

        case ST_BREACH:
            lcd_top = "BREACH: IN FIELD";
            buzzer_pattern(now, 1);                      /* every fitted buzzer sounds */
            if ((now - state_since) >= BREACH_MS) {
                relay_set(0);
                buzzer_pattern(now, 0);
                go(ST_COOLDOWN, now);
            }
            break;

        case ST_COOLDOWN:
            lcd_top = "COOLDOWN";
            relay_set(0);
            buzzer_pattern(now, 0);
            chirp_off();
            ir_flag = 0;
            if ((now - state_since) >= COOLDOWN_MS) {
                go(ST_SECURE, now);
            }
            break;

        default:
            go(ST_SECURE, now);
            break;
        }

        indicators(now);          /* all LED decisions, including the shared PA5 */

        /* ---------- LCD: only rewrite when the message actually changes ---------- */
        if (lcd_ok && lcd_top != lcd_shown && (now - last_lcd) >= LCD_REFRESH_MS) {
            char l2[17];
            last_lcd  = now;
            lcd_shown = lcd_top;
            make_line2(l2);
            lcd_line(0, lcd_top);
            lcd_line(1, l2);
        }

        /* ---------- heartbeat to the phone every 5 s ---------- */
        if ((now - last_beacon) >= 5000u) {
            last_beacon = now;
            send_status();
        }
    }
}
